    new Deposited(1000),
    new Withdrawn(200),
    new Deposited(100)
);

// Reconstruct current state by folding events
int balance = events.stream()
    .reduce(0,
        (acc, e) -> e instanceof Deposited d ? acc + d.amount()
                  : e instanceof Withdrawn w  ? acc - w.amount()
                  : acc,
        Integer::sum);
// balance == 900

