import java.util.*;
import java.util.function.Consumer;

public class EventBus {
    private final Map<Class<?>, List<Consumer<Object>>> handlers = new HashMap<>();

    @SuppressWarnings("unchecked")
    public <T> void subscribe(Class<T> type, Consumer<T> handler) {
        handlers.computeIfAbsent(type, k -> new ArrayList<>()).add(e -> handler.accept(type.cast(e)));
    }

    public void publish(Object event) {
        handlers.getOrDefault(event.getClass(), List.of()).forEach(h -> h.accept(event));
    }

    record SpellCast(String name, int damage) {}
    record MageLoggedIn(String username) {}

    public static void main(String[] args) {
        EventBus bus = new EventBus();
        bus.subscribe(SpellCast.class, e -> System.out.println("Spell fired: " + e.name()));
        bus.subscribe(MageLoggedIn.class, e -> System.out.println("Mage arrived: " + e.username()));
        bus.publish(new SpellCast("Fireball", 300));
        bus.publish(new MageLoggedIn("Lyria"));
    }
}

