import java.util.*;

public class SpellBook {
    sealed interface SpellEvent permits SpellBook.SpellAdded, SpellBook.SpellRemoved {}
    record SpellAdded(String name, int damage) implements SpellEvent {}
    record SpellRemoved(String name) implements SpellEvent {}

    private final List<SpellEvent> eventLog = new ArrayList<>();

    void addSpell(String name, int damage) { eventLog.add(new SpellAdded(name, damage)); }
    void removeSpell(String name)           { eventLog.add(new SpellRemoved(name)); }

    Map<String, Integer> currentState() {
        Map<String, Integer> state = new LinkedHashMap<>();
        for (SpellEvent e : eventLog) {
            if (e instanceof SpellAdded a) state.put(a.name(), a.damage());
            else if (e instanceof SpellRemoved r) state.remove(r.name());
        }
        return state;
    }

    public static void main(String[] args) {
        SpellBook sb = new SpellBook();
        sb.addSpell("Fireball", 300);
        sb.addSpell("Frost", 150);
        sb.removeSpell("Fireball");
        Map<String, Integer> state = sb.currentState();
        System.out.println("currentState: " + state);
        System.out.println("Frost=" + state.get("Frost"));
    }
}
